def hasact(adm, prefix, target, dest):
    for a in adm or []:
        s = text(a)
        if s.startswith(prefix) and (not target or target in s) and (not dest or dest in s):
            return True
    return False

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    else:
        act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
        if act.startswith(verb + ' ') and target and target in act:
            nb['transformed'] = True
    inv = text(val(ctx, 'world.inventory', ''))
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    pc = val(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = val(ctx, 'world.placed_locations', nb.get('placed_locations', []))
    if isinstance(locs, (list, tuple, set)):
        nb['placed_locations'] = [text(x) for x in locs]
    items = val(ctx, 'world.placed_items', nb.get('placed_items', []))
    if isinstance(items, (list, tuple, set)):
        nb['placed_items'] = [text(x) for x in items]
    adm = ctx.get('admissible', []) or []
    takeok = hasact(adm, 'take ', target, '')
    putok = hasact(adm, 'put ', target, dest)
    transok = bool(verb and hasact(adm, verb + ' ', target, ''))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and putok:
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif takeok:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_verb'] = verb
    return None

