def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(val(ctx, 'task.task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the target type; do not place it at the destination. Recover by setting it down only if needed, then search for the target.'
    elif stage == 'transform' and verb:
        msg = 'This target still needs the required ' + verb + ' step before any destination put. Use an admissible ' + verb + ' action while carrying it.'
    elif stage == 'put_target' and dest:
        msg = 'You are at the destination with the target; use the admissible put action for ' + target + ' in/on ' + dest + '.'
    elif stage == 'take_target' and target:
        msg = 'A target ' + target + ' is available here; take it instead of continuing to search.'
    elif stage == 'find_target' and 'two' in (nb.get('task_type') or '') and nb.get('placed_count', 0) > 0:
        msg = 'One target is already placed; leave it there, find another ' + target + ', and use the same destination type.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

