def hook(ctx, nb):
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(tt)
    if not verb or not target:
        return None
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    adm = ctx.get('admissible', []) or []
    carrying = bool(target in text(val(ctx, 'world.inventory', '')))
    if act.startswith('put ') and target in act and dest and dest in act and not nb.get('transformed') and hasact(adm, verb + ' ', target, ''):
        return {'kind': 'block_and_prompt', 'message': 'Do not put the target in the destination yet. First use the available ' + verb + ' action, then place it.'}
